-- Hosbah (P4): a destructive MCP call held for a human.
--
-- When the team has require_destructive_approval on, a destructive tool does not act. It records
-- what it WOULD have done and answers in-band with the request id; an owner or admin then approves
-- it in the dashboard, and the caller retries the same call, which now runs once and burns the
-- approval. So the row is a one-shot capability, not a log: `used` is terminal and a used row can
-- never authorise a second call.
--
-- args_summary is a redacted JSON echo of the call's arguments — it exists so the approver can see
-- what they are approving. Values are never copied into it verbatim: only argument NAMES and the
-- resource the tool resolved (see internal/mcp/approval.go). A secret must never reach this table,
-- because approvals are listed in the dashboard and returned over the API.
--
-- token_id is the MCP token that asked. It is the whole point of the audit trail: "which machine
-- credential tried to delete this", answerable without guessing from user_id alone.
ALTER TABLE approval_requests ADD CONSTRAINT approval_requests_status_check
  CHECK (status IN ('pending', 'approved', 'rejected', 'used', 'expired'));
-- 'team' (added MH-575 H2/H3): deleting a team-level notification channel or status page.
ALTER TABLE approval_requests ADD CONSTRAINT approval_requests_resource_type_check
  CHECK (resource_type IN ('app', 'server', 'database', 'domain', 'data_service', 'backup', 'invitation', 'member', 'team', 'log_drain'));
ALTER TABLE approval_requests ADD CONSTRAINT approval_requests_decided_check
  CHECK ((status IN ('pending', 'expired')) = (decided_by IS NULL));
CREATE UNIQUE INDEX approval_requests_id_team_key ON approval_requests (id, team_id);
CREATE INDEX approval_requests_team_status_idx ON approval_requests (team_id, status, created_at);
-- One live request per (token, tool, resource): a retrying client reuses its own pending or
-- approved row instead of filling the approver's queue with identical asks.
CREATE UNIQUE INDEX approval_requests_open_key ON approval_requests (team_id, token_id, tool, resource_type, resource_name)
  WHERE status IN ('pending', 'approved');
